import json
from pathlib import Path
root=Path(__file__).parent
originals={p['id']:p for fp in root.glob('originals-*.json') for p in json.loads(fp.read_text())}
rows=[]
def page(id,title,html):rows.append({'id':id,'title':title,'html':html,'url':originals[id]['links'][0]})
links='<p><a href="/pro-analytics-guide/">Pro Analytics Guide</a> · <a href="/?page_id=3066">Company Setup and Quick Start</a> · <a href="/pro-analytics/#account-connections">Open Company Connections</a></p>'
page('8082','2.A-4c Connect Pro Analytics','''<h2>Connect Your Company Reporting</h2><p>Pro Analytics runs in your company workspace at Social Media Magnet Pro. You do not install the old Westgate Analytics weekly-post plugin, regenerate an SMM access token or enter classroom dates on the customer website.</p><ol><li>Confirm the company in Pro Analytics.</li><li>Save the company website, logo, provider choice and intended market under Account → Company.</li><li>The Owner completes the appropriate provider connection under Account → Connections and confirms the selected GA4 property, email account/audience and social Page/account.</li><li>Your website administrator separately verifies working GA4 tracking and the configured form and phone events. Authorization does not install tracking.</li><li>Apply a date range with available data, wait for completion and save a baseline Report.</li></ol><p>Shared developer application settings belong to the platform administrator. Enter any company-specific provider credential only in its intended settings field. Team members use the roles and connections provided by their company.</p>'''+links)
page('8078','2.A-4b Email Signup, Forms and Measurement','''<h2>Build a Useful Signup and Next Action</h2><p>Your website forms should serve the audience and support the Brand Promise. Use the email provider and form system that fit your existing business website; Mailchimp, Constant Contact and website form tools are separate from the Pro Analytics reporting connection.</p><h3>Email Signup</h3><ol><li>Choose the audience/list in your email provider and state clearly what subscribers will receive.</li><li>Use the provider’s supported signup integration or a compatible form integration on your website. Confirm that a test signup reaches the intended audience and follows the provider’s confirmation settings.</li><li>Provide a clear success message and useful next step. If using a thank-you page, verify its actual URL and behavior.</li><li>Check the signup on desktop and mobile, including validation, confirmation and the delivered email.</li></ol><h3>Enquiry and Other Forms</h3><p>Use your existing website form tool, such as Ninja Forms where appropriate. Confirm that the notification reaches the right business inbox and the visitor receives the expected confirmation. A recorded submission is not automatically a qualified lead.</p><h3>Measure with GA4 Events</h3><p>Replace the old View → Goals → Destination procedure with verified GA4 events. Ask your website/analytics administrator to identify and test the intended signup, enquiry or phone-link event. Do not count a thank-you-page refresh as another successful business outcome. Mark important events as key events in GA4 when that is the intended definition.</p><p>Confirm separately which configured form and phone events Pro Analytics uses. Goal events per 100 sessions is an event-frequency measure, not a customer conversion percentage. Use a separately configured GA4 Funnel exploration when you need step-by-step drop-off analysis.</p><h3>Connect Reporting</h3><p>The Owner selects Mailchimp or Constant Contact under Account and completes the connection. Confirm the connected account/audience and selected report dates. No manual per-email campaign-ID entry is required in the Pro Analytics workflow.</p><p><a href="/?page_id=1285">Read Chapter 7.5: GA4 Events and the Goal Funnel</a></p>'''+links)
page('461','2.A-4 Website and Reporting Readiness','''<h2>Prepare Your Existing Business Website</h2><p>Use the website and provider accounts your business already operates. The Pro Analytics workflow does not require a new classroom domain, a branded Gmail account or the legacy SMM weekly reporting plugin.</p><ul><li><strong>Website:</strong> confirm ownership/access, a working mobile experience, useful Brand hub content and a clear next action.</li><li><strong>Publishing:</strong> verify the site’s actual URLs and campaign links. The SMM blog convention is /blog/.</li><li><strong>Email and forms:</strong> confirm delivery, the intended audience/list, notifications and success messages.</li><li><strong>Website analytics:</strong> verify the correct GA4 property, installed tracking and event definitions with the website administrator.</li><li><strong>Pro Analytics:</strong> the Owner connects the reporting providers in the company workspace and confirms each displayed identity.</li><li><strong>Baseline:</strong> select meaningful reporting dates and record the launch and change dates in the publishing calendar.</li></ul><p>Website construction and optional WordPress tools are separate from reporting authorization. If your site uses another platform, retain that platform and use its supported tracking and form integrations.</p><p><a href="/?page_id=8078">Email Signup, Forms and Measurement</a> · <a href="/?page_id=8082">Connect Pro Analytics</a></p>'''+links)
page('5921','6.A-2 Email Connection Readiness','''<h2>Prepare Your Email Reporting Connection</h2><p>Select the provider your company uses—Mailchimp or Constant Contact—and confirm that the account owner can authorize the intended account/audience. Then complete the provider-specific connection shown under Pro Analytics → Account → Connections.</p><p>Do not submit a login password, security-question answers or authentication codes through a course form or email. The old Mailchimp Security Form is no longer part of the Pro workflow. Shared application credentials are managed by the platform administrator; any required company-specific credential is entered only in the intended settings field.</p><ol><li>Confirm the company and provider.</li><li>Complete the appropriate connection and check its saved status.</li><li>Choose dates that include a known send and allow for provider response time.</li><li>Check totals and definitions before interpreting the result.</li></ol>'''+links)
page('2800','8.A-2 Check Email Reporting','''<h2>Check the Reporting after a Send</h2><p>Pro Analytics uses the company’s connected email provider. You do not extract campaign IDs from unsubscribe links or paste a number into the old weekly analytics plugin after each email.</p><ol><li>Confirm the company and connected Mailchimp or Constant Contact account.</li><li>Choose a reporting range that includes the send date, then apply dates and wait for the completed Report.</li><li>Read the provider’s counts and rates with their definitions. Responses may be lifetime-to-date for campaigns selected by send date.</li><li>Allow comparable response time before comparing messages.</li><li>Inspect attributable website visits and the intended goal events alongside provider clicks.</li></ol><p>If a send is missing, check dates, provider status and access. Missing data is not zero and does not represent a course grade.</p>'''+links)
for id,title in [('2489','Live Campaign Analytics'),('2487','Member Analytics')]:
 page(id,title,'<h2>Continue to Pro Analytics</h2><p>Your company’s current reporting workspace is Pro Analytics. Open Report for results, Review for saved Pro Analytics Reviews and Account for company connections and team access. The Pro workflow uses selected periods and comparisons, rather than cumulative classroom grades.</p><p><a href="/pro-analytics/">Open Pro Analytics Dashboard →</a></p>'+links)
(root/'setup-updates-2026-10-20_07-08_CT.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2))
print([r['id'] for r in rows])
